-- Snippets and shortcuts

local function sprintf(formatString, ...)
    return formatString:format(...)
end

local srep = string.rep

local function lpad(s, l, c)
    local res = srep(c or ' ', l - #s) .. s
    return res, res ~= s
end

local function rpad(s, l, c)
    local res = s .. srep(c or ' ', l - #s)
    return res, res ~= s
end

local function cpad(s, l, c)
    c = c or ' '
    local res1, stat1 = rpad(s, (l /2 ) + #s, c)
    local res2, stat2 = lpad(res1, l, c)
    return res2, stat1 or stat2
end

local RPTypes = {
    "",
    "Casual ",
    "Social ",
    "Adventure ",
    "Exploration ",
    "Training ",
    "Education ",
}

local function GetRPType(rpType)
    for i, val in ipairs(RPTypes) do
        if LocaleAwareToLower(rpType) .. " " == LocaleAwareToLower(val) then
            -- ROLE_PLAY_FINDER_MANAGER:Echo("%s = %s", rpType, val)
            return i
        else
            -- ROLE_PLAY_FINDER_MANAGER:Echo("%s is not %s", rpType, LocaleAwareToLower(val))
        end
    end
    ROLE_PLAY_FINDER_MANAGER:Echo("RP Type '%s' not found", rpType)
    return 1
end

