local RPFinder = ZO_Object:Subclass()

function RPFinder:New(...)
    local obj = ZO_Object.New(self)
    obj:Initialize(...)
    return obj
end

function RPFinder:Initialize(...)
    self:BuildGroupFinder()

    self.isCreated = false

    self.RPDetails = {}

    self.RPDetails.Type = 1
    self.RPDetails.Guild = 0
    self.RPDetails.GuildOnly = 0
    self.RPDetails.ZoneIndex = 0
    self.RPDetails.UsesDice = 0
    self.RPDetails.LocationType = LOCATION_TYPE_WORLD
    self.RPDetails.X = 0 -- If player house, players name
    self.RPDetails.Y = 0 -- If playe rhouse, house ID
    self.RPDetails.Owner = "None"
end

function RPFinder:BuildDetails()
    self:FetchLocationData()
    local details = sprintf("%d:%d:%d:%d:%d:%d:%d:%d:%s:", self.RPDetails.Type,
            self.RPDetails.Guild,
            self.RPDetails.GuildOnly,
            self.RPDetails.UsesDice,
            self.RPDetails.LocationType,
            self.RPDetails.ZoneIndex,
            self.RPDetails.X, -- Will be house number if it's a home
            self.RPDetails.Y,
            self.RPDetails.Owner
    )
    self.RPDetails.DetailString = details
end

-- Determine if the player is in a home or open world, and fill out data accordingly
function RPFinder:FetchLocationData()
    local houseId = GetCurrentZoneHouseId()
    if (houseId and houseId > 0) then
        local owner = GetCurrentHouseOwner()
        self.RPDetails.LocationType = LOCATION_TYPE_HOUSING
        self.RPDetails.Owner = owner
        self.RPDetails.ZoneIndex = houseId
        return
    else
        self.RPDetails.LocationType = LOCATION_TYPE_WORLD
        self.RPDetails.X = 0
        self.RPDetails.Owner = ""
        self.RPDetails.ZoneIndex = GetUnitZoneIndex("player")
    end
end

function RPFinder:GetRPData(line)
    local data = {}

    for str in string.gmatch(line, "[^:]+") do
        table.insert(data, str)
    end

--    for i, info in ipairs(data) do
--        df("Data: %d %s", i, info)
--    end

    local dataRP = {}
    dataRP.Type = tonumber(data[1])
    dataRP.Guild = tonumber(data[2])
    dataRP.GuildOnly = tonumber(data[3])
    dataRP.UsesDice = tonumber(data[4])
    dataRP.LocationType = tonumber(data[5])
    dataRP.ZoneIndex = tonumber(data[6])
    dataRP.X = tonumber(data[7])
    dataRP.Y = tonumber(data[8])
    dataRP.Owner = data[9]

    return dataRP
end

