    end

    dbresults = self.GroupFinderResults

    --df("Proceeding to scan %d results...", #self.GroupFinderResults)

    local RPCount = 0

    for i, data in ipairs(self.GroupFinderResults) do
        -- Is it a custom category?
        if (data:GetCategory() == 6) then
            -- Does it contain the RP string
            local description = data:GetDescription()
            local tagStart, tagEnd = string.find(description, "#rp:")
            if (tagEnd) then
                local firstExtract = string.sub(description, tagEnd + 1)
                local tagStart2, tagEnd2= string.find(firstExtract, "#rp")
                local extract = string.sub(firstExtract, 1, tagStart2 - 1)
                --df("%d %d: %s/%s", tagStart, tagEnd, firstExtract, extract)
