                end
                dataRP.groupFinderResult = data
                self.RPGroups[#self.RPGroups + 1] = ZO_ShallowTableCopy(dataRP)
                self.RPGroups[#self.RPGroups].groupFinderResult = data
            else
                --df("Tag not found")
                end
        else
            --df("Wrong category")
        end
    end
    if RPCount > 0 then
        --df("RPCount = %d", RPCount)
    end
end

