function RPFinder:GetGuildId(guildIndex)
    if not guildIndex then return 0 end
    guildIndex = tonumber(guildIndex)
    if guildIndex > 5 or guildIndex > GetNumGuilds() then
        return 0
    end
    return GetGuildId(guildIndex)
end

