function RPFinder:RemoveRPListing()
    if not self.isCreated then
        self:ColorEcho("lightgreen", "You have no RP Group Listed")
        return
    end
    RequestRemoveGroupListing()
    self:ColorEcho("goldenrod", "RP Group Listing Removed")
end

local numberOfListings = 0

function RPFinder:CreateRPListing()
    if not GROUP_FINDER_KEYBOARD then
        return
    end

    numberOfListings = numberOfListings + 1

    local data = GROUP_FINDER_KEYBOARD.createGroupListingContent.userTypeData
    data:SetCategory(6)
    self:BuildDetails()
    local description

    local locationName = GetPlayerLocationName()

    local rpType = self.RPDetails.Type or 1
    -- ROLE_PLAY_FINDER_MANAGER:Echo("TP Type: %d", rpType)
    local title = sprintf("%sRP at %s", RPTypes[rpType], locationName)
    data:SetTitle(title)

    -- TODO: Add RP type
    if self.RPDetails.LocationType == LOCATION_TYPE_HOUSING then
        local link = GetHousingLink(self.RPDetails.ZoneIndex, self.RPDetails.Owner)
        description = sprintf("RP at %s\n#rp:%s#rp!", link, self.RPDetails.DetailString)
    else
        description = sprintf("RP at %s\n#rp:%s#rp!", locationName, self.RPDetails.DetailString)
    end

    data:SetDescription(description)

    if data:GetUserType() == GROUP_FINDER_GROUP_LISTING_USER_TYPE_CREATED_GROUP_LISTING then
        --df("Editing RP Listing")
        RequestEditGroupListing()
    else
        --df("Creating RP Listing")
        RequestCreateGroupListing()
    end
end

-- Iterate through all RP groups, count local ones
function RPFinder:GetLocalRPCount()
    local RPCount = 0
    for k, value in pairs(self.RPGroups) do
        if (value.ZoneIndex == GetUnitZoneIndex("player")) then
            --df("Same Zone Index")
            RPCount = RPCount + 1
        end
    end
    -- self:ColorEcho("lightgreen", "RPCount: %d", RPCount)
    if RPCount > 0 then
        self:ColorEcho("lightgreen", "There is RP in this zone!  Type \"/rpfinder zone\" to see them.  Groups: %d", RPCount)
    end
end

