local function onPlayerActivated(name)
    --df("Player Activated!")
    if ROLE_PLAY_FINDER_MANAGER:GetCreated() then
        ROLE_PLAY_FINDER_MANAGER:CreateRPListing()
    end

    SetGroupFinderFilterCategory(6)
    GROUP_FINDER_SEARCH_MANAGER:ExecuteSearch()

    ROLE_PLAY_FINDER_MANAGER:BuildGroupFinder()
    ROLE_PLAY_FINDER_MANAGER:GetLocalRPCount()
    -- TODO: Only do this once
    if not ROLE_PLAY_FINDER_MANAGER.SlashCommands then
        ROLE_PLAY_FINDER_MANAGER.SlashCommands = LibSlashCommander

        local rpfCommand = ROLE_PLAY_FINDER_MANAGER.SlashCommands:Register(
                { "/rpfinder", "/finder" },
                function(input)
                    -- break up input
                    local splitInput = { zo_strsplit(" ", input) }
                    --ROLE_PLAY_FINDER_MANAGER:Echo("%s", splitInput[1] or input)
                    input = splitInput[1] or input
                    if (input == "create" or input == "new") then
                        if splitInput[2] then
                            --ROLE_PLAY_FINDER_MANAGER:Echo("Checking for RP type %s", splitInput[2])
                            local RPType = GetRPType(splitInput[2])
                            ROLE_PLAY_FINDER_MANAGER:SetRPType(RPType)
                        end

                        ROLE_PLAY_FINDER_MANAGER:ColorEcho("lightblue", "Creating new RP group...")
                        ROLE_PLAY_FINDER_MANAGER:CreateRPGroup()
                    elseif (input == "show") then
                        ROLE_PLAY_FINDER_MANAGER:ShowGroupFinder(GROUP_SHOW_ALL)
                    elseif (input == "zone") then
                        ROLE_PLAY_FINDER_MANAGER:ShowGroupFinder(GROUP_SHOW_ZONE)
                    elseif (input == "house") or input == "home" then
                        ROLE_PLAY_FINDER_MANAGER:ShowGroupFinder(GROUP_SHOW_HOUSING)
                    elseif (input == "guild") then
                        if not(splitInput[2]) then
                            local guildId = ROLE_PLAY_FINDER_MANAGER.RPDetails.Guild
                            local guildName = GetGuildName(guildId)
                            ROLE_PLAY_FINDER_MANAGER:ColorEcho("lightblue", "Your RP Group is linked to guild %s", guildName)
                        else
                            local guildId = ROLE_PLAY_FINDER_MANAGER:GetGuildId(splitInput[2])
                            ROLE_PLAY_FINDER_MANAGER.RPDetails.Guild = guildId
                            local guildName = GetGuildName(guildId)
                            ROLE_PLAY_FINDER_MANAGER:ColorEcho("lightblue", "Your RP Group is linked to guild %s", guildName)
                            ROLE_PLAY_FINDER_MANAGER:BuildDetails()
                            if ROLE_PLAY_FINDER_MANAGER:GetCreated() then
                                ROLE_PLAY_FINDER_MANAGER:CreateRPListing()
                            end
                        end
                    elseif (input == "usedice") then
                        local useDice = ROLE_PLAY_FINDER_MANAGER:GetUsesDice()
                        -- TODO: Different types of dice rules?
                        if useDice == 0 then
                            useDice = 1
                        else
                            useDice = 0
                        end
                        ROLE_PLAY_FINDER_MANAGER:SetUsesDice(useDice)
                        if (useDice == 1) then
                            ROLE_PLAY_FINDER_MANAGER:ColorEcho("lighblue", "Your RP Group uses dice.")
                        else
                            ROLE_PLAY_FINDER_MANAGER:ColorEcho("lighblue", "Your RP Group does not use dice.")
                        end
                        if ROLE_PLAY_FINDER_MANAGER:GetCreated() then
                            ROLE_PLAY_FINDER_MANAGER:CreateRPListing()
                        end

                    elseif (input == "end" or input == "remove") then
                        ROLE_PLAY_FINDER_MANAGER:RemoveRPListing()
                    end
                end
        )

        -- SLASH_COMMANDS["/rpfinder"] = function() ROLE_PLAY_FINDER_MANAGER:ShowGroupFinder() end
    end
end

