end

local function OnLinkClicked(linkData, button, linkText, color, linkType, ...)
    local command = {...}

    -- TODO: Right click menu?

    if linkType ~= "groupFind" or button ~= 1 then
        return false
    end

    if not command[1] then
        return
    end

    local index = tonumber(command[1])
    ROLE_PLAY_FINDER_MANAGER:Echo("Found Index %d", index)
    if (index and index > -1) then
        ROLE_PLAY_FINDER_MANAGER:ApplyToGroup(index)
    end
    return true
end

local function OnSearchResultsReady()
    -- Only build if results are for custom group
    if GetGroupFinderFilterCategory() == 6 then
        --ROLE_PLAY_FINDER_MANAGER:ColorEcho("red", "Search Results Ready, building...")
        ROLE_PLAY_FINDER_MANAGER:BuildGroupFinder()
    end
end

